selector_to_html = {"a[href=\"#co2-vdw\"]": "<div class=\"exercise admonition\" id=\"co2-vdw\">\n<p class=\"admonition-title\"><span class=\"caption-number\">Exercise 2.2 </span> (CO<span class=\"math notranslate nohighlight\">\\(_2\\)</span> in a box)</p>\n<section id=\"exercise-content\">\n<div class=\"sd-tab-set docutils\">\n<input checked=\"checked\" id=\"sd-tab-item-4\" name=\"sd-tab-set-2\" type=\"radio\"/>\n<label class=\"sd-tab-label\" for=\"sd-tab-item-4\">\n(a)</label><div class=\"sd-tab-content docutils\">\n<p>Use the van der Waals equation of state to calculate and plot <span class=\"math notranslate nohighlight\">\\(P(T)_V\\)</span> for <span class=\"math notranslate nohighlight\">\\(1\\, \\mathrm{mol\\ CO_2}\\)</span> for the given temperatures (<code class=\"docutils literal notranslate\"><span class=\"pre\">Temps</span></code>), at volumes:</p>\n<ul class=\"simple\">\n<li><p><span class=\"math notranslate nohighlight\">\\(V_1 = 0.50\\, \\mathrm{L}\\)</span></p></li>\n<li><p><span class=\"math notranslate nohighlight\">\\(V_2 = 0.30\\, \\mathrm{L}\\)</span></p></li>\n<li><p><span class=\"math notranslate nohighlight\">\\(V_3 = 0.10\\, \\mathrm{L}\\)</span></p></li>\n</ul>\n<p>The <span class=\"math notranslate nohighlight\">\\(a\\)</span> and <span class=\"math notranslate nohighlight\">\\(b\\)</span> parameters for <span class=\"math notranslate nohighlight\">\\(\\mathrm{CO_2}\\)</span> can be found in <a class=\"reference internal\" href=\"#vdw-params\"><span class=\"std std-numref\">Table 2.2</span></a>.</p>\n</div>\n</div>\n</section>\n</div>", "a[href=\"#2d-state\"]": "<div class=\"exercise admonition\" id=\"2d-state\">\n<p class=\"admonition-title\"><span class=\"caption-number\">Exercise 2.1 </span> (Helium in a Box)</p>\n<section id=\"exercise-content\">\n<div class=\"sd-tab-set docutils\">\n<input checked=\"checked\" id=\"sd-tab-item-0\" name=\"sd-tab-set-0\" type=\"radio\"/>\n<label class=\"sd-tab-label\" for=\"sd-tab-item-0\">\n(a)</label><div class=\"sd-tab-content docutils\">\n<p>Use the ideal gas law to plot <span class=\"math notranslate nohighlight\">\\(P(T)\\)</span> from <span class=\"math notranslate nohighlight\">\\(T = 79\\)</span> to <span class=\"math notranslate nohighlight\">\\(298\\, \\mathrm{K}\\)</span> for <span class=\"math notranslate nohighlight\">\\(1.25\\, \\mathrm{mol}\\)</span> helium gas in a container with volume:</p>\n<ul class=\"simple\">\n<li><p>(i) <span class=\"math notranslate nohighlight\">\\(V = 0.01\\, \\mathrm{L}\\)</span></p></li>\n<li><p>(ii) <span class=\"math notranslate nohighlight\">\\(V = 0.1\\, \\mathrm{L}\\)</span></p></li>\n<li><p>(iii) <span class=\"math notranslate nohighlight\">\\(V = 1\\, \\mathrm{L}\\)</span></p></li>\n</ul>\n<div class=\"dropdown simple admonition\">\n<p class=\"admonition-title\">hint</p>\n<p>Always double check that all your units work out! The value of <span class=\"math notranslate nohighlight\">\\(R\\)</span> depends on the units you\u2019re using (see <a class=\"reference internal\" href=\"#r-values\"><span class=\"std std-numref\">Table 2.1</span></a>)</p>\n</div>\n</div>\n<input id=\"sd-tab-item-1\" name=\"sd-tab-set-0\" type=\"radio\"/>\n<label class=\"sd-tab-label\" for=\"sd-tab-item-1\">\n(b)</label><div class=\"sd-tab-content docutils\">\n<ul class=\"simple\">\n<li><p>How will each ideal gas model assumption influence the accuracy using the ideal gas equation of state to model these systems?</p></li>\n<li><p>Which systems from (a) would you expect the ideal gas model to describe best and worst? Why?</p></li>\n</ul>\n</div>\n</div>\n</section>\n</div>", "a[href=\"#true\"]": "<aside class=\"footnote brackets\" id=\"true\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span><a href=\"#id2\" role=\"doc-backlink\">2</a><span class=\"fn-bracket\">]</span></span>\n<p>defining what it means for something to be \u201ctrue\u201d is, it turns out, not simple\u2013especially when discussing models, all of which are flawed in some way.</p>\n</aside>", "a[href=\"#corp\"]": "<aside class=\"footnote brackets\" id=\"corp\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span><a href=\"#id3\" role=\"doc-backlink\">3</a><span class=\"fn-bracket\">]</span></span>\n<p>A term commonly used for a discrete particle of matter before concepts of \u201catoms\u201d and \u201cmolecules\u201d were introduced. For example, in his 1738 book Hydrodynamica, Daniel Bernoulli wrote <em>\u201clet the cavity contain very minute corpuscles, which are driven hither and thither with a very rapid motion; so that these corpuscles, when they strike against the piston and sustain it by their repeated impacts, form an elastic fluid which will expand of itself if the weight is removed or diminished\u2026\u201d</em></p>\n</aside>", "a[href=\"#the-ideal-gas-equation-of-state\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.1. </span>The Ideal Gas Equation of State<a class=\"headerlink\" href=\"#the-ideal-gas-equation-of-state\" title=\"Link to this heading\">#</a></h2><p>Physical quantities needed to specify thestate of a gaseous system include the amount of substance <span class=\"math notranslate nohighlight\">\\(n\\)</span>, the volume <span class=\"math notranslate nohighlight\">\\(V\\)</span> it occupies, its temperature <span class=\"math notranslate nohighlight\">\\(T\\)</span>, and its pressure <span class=\"math notranslate nohighlight\">\\(P\\)</span>. If these quantities are sufficient to describe the entire system, we should be able to formulate one in terms of the others. In other words: if <span class=\"math notranslate nohighlight\">\\(n\\)</span>, <span class=\"math notranslate nohighlight\">\\(V\\)</span>, <span class=\"math notranslate nohighlight\">\\(T\\)</span>, and <span class=\"math notranslate nohighlight\">\\(P\\)</span> are a full minimal set of <strong>state variables</strong>, then we should be able to formulate a function:</p>", "a[href=\"#the-van-der-waals-equation-of-state\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.2. </span>The van der Waals Equation of State<a class=\"headerlink\" href=\"#the-van-der-waals-equation-of-state\" title=\"Link to this heading\">#</a></h2><p>Johannes van der Waals derived a modified ideal gas law in an attempt to better capture the experimentally-observed behavior of gases.</p><p>The assumption that the volume occupied by particles is neglibly different from the container volume (<span class=\"math notranslate nohighlight\">\\(V_\\text{free} = V_\\text{container} = V\\)</span>) would only be true if the particles themselves take up no space.<a class=\"footnote-reference brackets\" href=\"#point-particle\" id=\"id6\" role=\"doc-noteref\"><span class=\"fn-bracket\">[</span>6<span class=\"fn-bracket\">]</span></a> However, in actuality gas particles <em>do</em> take up space. van der Waals\u2019 equation of state aims to account for this by instead employing the <strong>effective volume</strong> (<span class=\"math notranslate nohighlight\">\\(V_\\text{eff})\\)</span>:</p>", "a[href=\"#term-equation-of-state\"]": "<dt id=\"term-equation-of-state\">equation of state</dt><dd><p>A mathematical function that describes the state of a system, based on system parameters.</p></dd>", "a[href=\"#mechanical-properties-p-v-n\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2. </span>Mechanical Properties (P,V,n)<a class=\"headerlink\" href=\"#mechanical-properties-p-v-n\" title=\"Link to this heading\">#</a></h1><p>Theoretical and mathematical models can be used to describe and predict properties and behavior of systems. These models often have conceptual implications. If the model matches experimental data, unpacking the \u201cstory\u201d the model conveys can deepen our understanding of <em>how</em> and <em>why</em> systems behave the way they do. This chapters explores how to develop, use, and evaluate theoretical and mathematical models predicting <a class=\"reference internal\" href=\"#term-mechanical-properties\"><span class=\"xref std std-term\">mechanical properties</span></a> (e.g., <span class=\"math notranslate nohighlight\">\\(P\\)</span>,<span class=\"math notranslate nohighlight\">\\(V\\)</span>, <span class=\"math notranslate nohighlight\">\\(n\\)</span>) of the state of gaseous systems.</p>", "a[href=\"#gases\"]": "<aside class=\"footnote brackets\" id=\"gases\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span><a href=\"#id1\" role=\"doc-backlink\">1</a><span class=\"fn-bracket\">]</span></span>\n<p>I suspect you are surrounded by them right now.</p>\n</aside>", "a[href=\"#vdw-source\"]": "<aside class=\"footnote brackets\" id=\"vdw-source\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span><a href=\"#id7\" role=\"doc-backlink\">7</a><span class=\"fn-bracket\">]</span></span>\n<p>Weast, R. C., Ed. <em>CRC Handbook of Chemistry and Physics</em>, 53rd ed.; Chemical Rubber Co.: Cleveland, OH, 1972.</p>\n</aside>", "a[href=\"#term-mechanical-properties\"]": "<dt id=\"term-mechanical-properties\">mechanical properties</dt><dd><p>Mechanical properties describe a physical object\u2019s relationships between force and motion. For a gas, key mechanical properties include pressure (<span class=\"math notranslate nohighlight\">\\(P\\)</span>), volume (<span class=\"math notranslate nohighlight\">\\(V\\)</span>), and number of moles (<span class=\"math notranslate nohighlight\">\\(n\\)</span>). Notably, temperature is not a mechanical property (although it does influence a system\u2019s mechanical properties).</p></dd>", "a[href=\"#equipart\"]": "<aside class=\"footnote brackets\" id=\"equipart\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span><a href=\"#id5\" role=\"doc-backlink\">5</a><span class=\"fn-bracket\">]</span></span>\n<p>per the equipartition theorem</p>\n</aside>", "a[href=\"#point-particle\"]": "<aside class=\"footnote brackets\" id=\"point-particle\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span><a href=\"#id6\" role=\"doc-backlink\">6</a><span class=\"fn-bracket\">]</span></span>\n<p>this is sometimes described as the ideal gas law assuming gases are made up of \u201cpoint particles\u201d that have no volume.</p>\n</aside>", "a[href=\"#glossary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.3. </span>Glossary<a class=\"headerlink\" href=\"#glossary\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#vdw-params\"]": "<table class=\"table\" id=\"vdw-params\">\n<caption><span class=\"caption-number\">Table 2.2 </span><span class=\"caption-text\">van der Waals <span class=\"math notranslate nohighlight\">\\(a\\)</span> and <span class=\"math notranslate nohighlight\">\\(b\\)</span> parameters for select substances<a class=\"footnote-reference brackets\" href=\"#vdw-source\" id=\"id7\" role=\"doc-noteref\"><span class=\"fn-bracket\">[</span>7<span class=\"fn-bracket\">]</span></a></span><a class=\"headerlink\" href=\"#vdw-params\" title=\"Link to this table\">#</a></caption>\n<thead>\n<tr class=\"row-odd\"><th class=\"head text-left\"><p>Substance</p></th>\n<th class=\"head text-center\"><p><span class=\"math notranslate nohighlight\">\\(a\\)</span> (L<span class=\"math notranslate nohighlight\">\\(^2\\)</span>bar/mol<span class=\"math notranslate nohighlight\">\\(^2\\)</span>)</p></th>\n<th class=\"head text-center\"><p><span class=\"math notranslate nohighlight\">\\(b\\)</span> (L/mol)</p></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Acetic Acid</p></td>\n<td class=\"text-center\"><p>17.7098</p></td>\n<td class=\"text-center\"><p>0.1065</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Acetone</p></td>\n<td class=\"text-center\"><p>16.02</p></td>\n<td class=\"text-center\"><p>0.1124</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Ammonia</p></td>\n<td class=\"text-center\"><p>4.225</p></td>\n<td class=\"text-center\"><p>0.0371</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Argon</p></td>\n<td class=\"text-center\"><p>1.355</p></td>\n<td class=\"text-center\"><p>0.03201</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Benzene</p></td>\n<td class=\"text-center\"><p>18.24</p></td>\n<td class=\"text-center\"><p>0.1193</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Bromobenzene</p></td>\n<td class=\"text-center\"><p>28.94</p></td>\n<td class=\"text-center\"><p>0.1539</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Carbon dioxide</p></td>\n<td class=\"text-center\"><p>3.6</p></td>\n<td class=\"text-center\"><p>0.04267</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Carbon disulfide</p></td>\n<td class=\"text-center\"><p>11.77</p></td>\n<td class=\"text-center\"><p>0.07685</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Carbon monoxide</p></td>\n<td class=\"text-center\"><p>1.505</p></td>\n<td class=\"text-center\"><p>0.03985</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Carbon tetrachloride</p></td>\n<td class=\"text-center\"><p>19.7483</p></td>\n<td class=\"text-center\"><p>0.1281</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Chlorobenzene</p></td>\n<td class=\"text-center\"><p>25.77</p></td>\n<td class=\"text-center\"><p>0.1453</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Ethane</p></td>\n<td class=\"text-center\"><p>5.562</p></td>\n<td class=\"text-center\"><p>0.0638</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Ethanethiol</p></td>\n<td class=\"text-center\"><p>11.39</p></td>\n<td class=\"text-center\"><p>0.08098</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Ethanol</p></td>\n<td class=\"text-center\"><p>12.18</p></td>\n<td class=\"text-center\"><p>0.08407</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Freon</p></td>\n<td class=\"text-center\"><p>10.78</p></td>\n<td class=\"text-center\"><p>0.0998</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Helium</p></td>\n<td class=\"text-center\"><p>0.0346</p></td>\n<td class=\"text-center\"><p>0.0238</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Hexane</p></td>\n<td class=\"text-center\"><p>24.71</p></td>\n<td class=\"text-center\"><p>0.1735</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Hydrogen</p></td>\n<td class=\"text-center\"><p>0.2476</p></td>\n<td class=\"text-center\"><p>0.02661</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Hydrogen bromide</p></td>\n<td class=\"text-center\"><p>4.510</p></td>\n<td class=\"text-center\"><p>0.04431</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Hydrogen chloride</p></td>\n<td class=\"text-center\"><p>3.716</p></td>\n<td class=\"text-center\"><p>0.04081</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Krypton</p></td>\n<td class=\"text-center\"><p>2.349</p></td>\n<td class=\"text-center\"><p>0.03978</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Methane</p></td>\n<td class=\"text-center\"><p>2.283</p></td>\n<td class=\"text-center\"><p>0.04278</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Methanol</p></td>\n<td class=\"text-center\"><p>9.649</p></td>\n<td class=\"text-center\"><p>0.06702</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Neon</p></td>\n<td class=\"text-center\"><p>0.2135</p></td>\n<td class=\"text-center\"><p>0.01709</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Nitrogen</p></td>\n<td class=\"text-center\"><p>1.370</p></td>\n<td class=\"text-center\"><p>0.0397</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Oxygen</p></td>\n<td class=\"text-center\"><p>1.382</p></td>\n<td class=\"text-center\"><p>0.03186</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Pentane</p></td>\n<td class=\"text-center\"><p>19.26</p></td>\n<td class=\"text-center\"><p>0.146</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Propane</p></td>\n<td class=\"text-center\"><p>8.779</p></td>\n<td class=\"text-center\"><p>0.08445</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Radon</p></td>\n<td class=\"text-center\"><p>6.601</p></td>\n<td class=\"text-center\"><p>0.06239</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Toluene</p></td>\n<td class=\"text-center\"><p>24.38</p></td>\n<td class=\"text-center\"><p>0.1463</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Water</p></td>\n<td class=\"text-center\"><p>5.536</p></td>\n<td class=\"text-center\"><p>0.03049</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Xenon</p></td>\n<td class=\"text-center\"><p>4.250</p></td>\n<td class=\"text-center\"><p>0.05105</p></td>\n</tr>\n</tbody>\n</table>", "a[href=\"#ideal-gas\"]": "<aside class=\"footnote brackets\" id=\"ideal-gas\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span><a href=\"#id4\" role=\"doc-backlink\">4</a><span class=\"fn-bracket\">]</span></span>\n<p>or, equivalently: <span class=\"math notranslate nohighlight\">\\(PV = nRT\\)</span></p>\n</aside>", "a[href=\"#r-values\"]": "<table class=\"table\" id=\"r-values\">\n<caption><span class=\"caption-number\">Table 2.1 </span><span class=\"caption-text\"><span class=\"math notranslate nohighlight\">\\(R\\)</span> constant values</span><a class=\"headerlink\" href=\"#r-values\" title=\"Link to this table\">#</a></caption>\n<thead>\n<tr class=\"row-odd\"><th class=\"head text-center\"><p>value</p></th>\n<th class=\"head text-left\"><p>units</p></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"row-even\"><td class=\"text-center\"><p><span class=\"math notranslate nohighlight\">\\(8.31446\\)</span></p></td>\n<td class=\"text-left\"><p><span class=\"math notranslate nohighlight\">\\(\\mathrm{\\frac{J}{K \\cdot mol}}\\)</span></p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-center\"><p><span class=\"math notranslate nohighlight\">\\(8314.46\\)</span></p></td>\n<td class=\"text-left\"><p><span class=\"math notranslate nohighlight\">\\(\\mathrm{\\frac{L \\cdot Pa}{K \\cdot mol}}\\)</span></p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-center\"><p><span class=\"math notranslate nohighlight\">\\(0.08206\\)</span></p></td>\n<td class=\"text-left\"><p><span class=\"math notranslate nohighlight\">\\(\\mathrm{\\frac{L \\cdot atm}{K \\cdot mol}}\\)</span></p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-center\"><p><span class=\"math notranslate nohighlight\">\\(8.2057\\cdot 10^{-5}\\)</span></p></td>\n<td class=\"text-left\"><p><span class=\"math notranslate nohighlight\">\\(\\mathrm{\\frac{m^3 \\cdot atm}{K \\cdot mol}}\\)</span></p></td>\n</tr>\n</tbody>\n</table>"}
skip_classes = ["headerlink", "sd-stretched-link", "exercise", "solution"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'top', maxWidth: 500, interactive: true, theme: 'light-border',
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
